(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-968":{scenario:{company:"Coralis Offshore Operating",supervisor:{name:"Châu Minh Tường",role:{vi:"Giám sát Vận hành Khai thác",en:"Production Superintendent"}},ref_code:"DPR-2810",title:{vi:"Phân loại đúng hao hụt. Tính đúng dầu thực.",en:"Classify deferment right. Count net oil."},brief:{vi:"Bạn hoàn thiện báo cáo hao hụt sản lượng ngày 28/10, hồ sơ DPR-2810, của một giàn khai thác. Máy nén khí gaslift K-201 trip bất ngờ do rung cao, giếng W-12 dừng từ 03:12 đến 12:12 (9 giờ). Phép thử giếng hợp lệ gần nhất ngày 25/10: chất lỏng 2300 bbl/ngày, độ ngậm nước 20%. Sửa loại hao hụt và lượng dầu hao hụt trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are completing the 28/10 production deferment report, file DPR-2810, for an offshore platform. Gas lift compressor K-201 tripped unexpectedly on high vibration and well W-12 was shut in from 03:12 to 12:12 (9 hours). The latest valid well test on 25/10: liquid 2300 bbl/d, water cut 20%. Correct the deferment category and the deferred oil volume in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Ma trận hao hụt & phép thử giếng đã duyệt · DPR-2810",en:"Approved deferment matrix & well tests · DPR-2810"},fields:[{id:"DEFER_CAT",label:{vi:"Phân loại hao hụt sản lượng",en:"Deferment category"},initial:"DEF-PLAN",expected:"DEF-UNPLAN",choices:["DEF-PLAN","DEF-UNPLAN","DEF-EXTERNAL"],reference:"Ma trận phân loại hao hụt",hint:{vi:"Sự cố thiết bị không nằm trong kế hoạch bảo dưỡng đã duyệt là hao hụt ngoài kế hoạch, dù thời gian dừng ngắn.",en:"An equipment failure outside the approved maintenance plan is unplanned deferment, however short the outage."}},{id:"DEFER_BBL",label:{vi:"Lượng dầu hao hụt (bbl)",en:"Deferred oil (bbl)"},initial:"862.5",expected:"690",reference:"Bảng tính hao hụt sản lượng",ref_value:{vi:"Phép thử hợp lệ 25/10: chất lỏng 2300 bbl/ngày, ngậm nước 20%; dừng 9 giờ",en:"Valid test 25/10: liquid 2300 bbl/d, water cut 20%; downtime 9 h"},hint:{vi:"Hao hụt tính trên dầu thực đã trừ nước, theo phép thử hợp lệ gần nhất và thời gian dừng quy về ngày.",en:"Deferment is counted on net oil after water, using the latest valid test and downtime converted to days."}}],sop32:{vi:"Dầu hao hụt (bbl) = lưu lượng chất lỏng của phép thử hợp lệ gần nhất x (1 - độ ngậm nước) x số giờ dừng / 24; không dùng phép thử đã bị thay thế.",en:"Deferred oil (bbl) = liquid rate of the latest valid well test x (1 - water cut) x hours down / 24; never use a superseded test."},context:{label:"DCS / DPR-2810",metrics:[{label:{vi:"Thời gian dừng W-12",en:"W-12 downtime"},value:"9 h"},{label:{vi:"Chất lỏng (phép thử 25/10)",en:"Liquid (25/10 test)"},value:"2,300 bbl/d"},{label:{vi:"Độ ngậm nước",en:"Water cut"},value:"20%"}]},crisis:{vi:"Trưởng ca nhắn: “Bypass liên động rung cao của K-201 rồi chạy lại ngay, tôi cử người đứng canh. Mất thêm vài giờ là trượt chỉ tiêu tháng, cứ ghi hao hụt theo kế hoạch cho đẹp báo cáo.”",en:"The shift supervisor messages you: “Bypass the K-201 high vibration trip and restart now, I will post someone to watch it. A few more hours and we miss the monthly target, just book it as planned deferment.”"},options:{safe:{vi:"Không bypass khi chưa có phiếu phê duyệt và đánh giá rủi ro, giữ K-201 dừng để kiểm tra rung và báo Tổng chỉ huy giàn (OIM); ghi đúng DEF-UNPLAN và tối ưu các giếng còn lại.",en:"Do not bypass without an approved override permit and risk assessment, keep K-201 down for vibration checks and inform the OIM; book DEF-UNPLAN and optimize the other wells."},shortcut:{vi:"Bypass liên động, chạy lại K-201 có người canh và ghi hao hụt theo kế hoạch.",en:"Bypass the trip, restart K-201 with a watchman and book the loss as planned."},wait:{vi:"Để trưởng ca tự quyết định, chờ ca sau hoàn thiện báo cáo.",en:"Let the shift supervisor decide and leave the report for the next shift."}},questions:{vi:["Vì sao sự cố K-201 là DEF-UNPLAN? Bằng chứng nào trong nhật ký và kế hoạch bảo dưỡng hỗ trợ kết luận?","Trình bày cách tính dầu hao hụt và rủi ro an toàn, pháp lý nếu bypass liên động rung cao khi chưa được phê duyệt."],en:["Why is the K-201 event DEF-UNPLAN? Which evidence in the logs and maintenance plan supports this?","Explain the deferred oil calculation and the safety and legal risk of bypassing the vibration trip without approval."]},hints:{vi:["Đối chiếu nhật ký cảnh báo với kế hoạch bảo dưỡng để biết sự cố có được lên kế hoạch hay không.","Chọn đúng phép thử còn hiệu lực, trừ nước rồi nhân thời gian dừng theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi bypass hệ thống an toàn cần phiếu phê duyệt, đánh giá rủi ro và người có thẩm quyền."],en:["Match the alarm log with the maintenance plan to see whether the outage was planned.","Pick the valid well test, remove water, then apply the downtime per SOP 3.2.","Re-read SOP 4.2: any safety system bypass needs an approved permit, a risk assessment and the responsible authority."]},terminal:{system:"dcs-prod",settable:["DEFER_CAT","DEFER_BBL"],commands:[{cmd:"alarm log",out:{vi:"03:12 K-201 trip rung cao 11.2 mm/s; 03:14 W-12 mất khí gaslift, van an toàn đóng; 12:12 W-12 mở lại sau khi K-201 chạy lại.",en:"03:12 K-201 trip on high vibration 11.2 mm/s; 03:14 W-12 lost lift gas, safety valve closed; 12:12 W-12 reopened after K-201 restart."}},{cmd:"well test w-12",out:{vi:"02/10: chất lỏng 2600 bbl/ngày, ngậm nước 15% (đã bị thay thế). 25/10: chất lỏng 2300 bbl/ngày, ngậm nước 20% (hợp lệ).",en:"02/10: liquid 2600 bbl/d, water cut 15% (superseded). 25/10: liquid 2300 bbl/d, water cut 20% (valid)."}},{cmd:"maint plan k-201",out:{vi:"Không có lệnh công việc bảo dưỡng theo kế hoạch cho K-201 trong tháng 10; lần bảo dưỡng kế tiếp 15/12.",en:"No planned maintenance work order for K-201 in October; next planned maintenance on 15/12."}},{cmd:"vib trend k-201",out:{vi:"Rung ổ đỡ phía dẫn động tăng từ 4.5 lên 11.2 mm/s trong 6 giờ trước khi trip.",en:"Drive-end bearing vibration rose from 4.5 to 11.2 mm/s in the 6 hours before the trip."}},{cmd:"cat override.log",out:{vi:"03:40 trưởng ca yêu cầu bypass liên động rung cao K-201: chưa có phiếu phê duyệt, chưa có đánh giá rủi ro.",en:"03:40 shift supervisor requested a K-201 vibration trip bypass: no approved permit, no risk assessment."}}]}},learning:{summary:{vi:"Kỹ sư vận hành khai thác dầu khí giám sát giếng và hệ thống xử lý bề mặt hằng ngày: tối ưu lưu lượng, khai thác cơ học bằng gaslift, thử giếng, phân bổ sản lượng và theo dõi hao hụt. Nghề giữ cho sản lượng ổn định mà vẫn an toàn tuyệt đối, đòi hỏi hiểu vỉa, giếng, thiết bị và kỷ luật với hệ thống an toàn công nghệ.",en:"An oil and gas production operations engineer oversees wells and surface facilities every day: rate optimization, gas lift, well testing, production allocation and deferment tracking. The role keeps production stable while staying absolutely safe, and requires knowledge of reservoirs, wells, equipment and discipline with process safety systems."},responsibilities:{vi:["Theo dõi lưu lượng, áp suất, độ ngậm nước và GOR của từng giếng theo ca.","Lập lịch và kiểm tra chất lượng phép thử giếng, cập nhật tiềm năng giếng.","Tối ưu khí gaslift, côn tiết lưu và phối hợp với nhóm vỉa để tăng thu hồi.","Lập báo cáo sản lượng ngày, phân bổ sản lượng và phân loại hao hụt.","Tuân thủ giấy phép làm việc, quản lý thay đổi và quy trình bypass hệ thống an toàn."],en:["Monitor rates, pressures, water cut and GOR for each well every shift.","Schedule and quality-check well tests and update well potentials.","Optimize lift gas and chokes and work with reservoir engineers to improve recovery.","Prepare the daily production report, allocation and deferment classification.","Follow permit to work, management of change and safety system bypass procedures."]},competencies:[{name:{vi:"Phân tích giếng",en:"Well performance analysis"},desc:{vi:"Dùng đường IPR, VLP và phân tích nút để chẩn đoán và tối ưu giếng.",en:"Use IPR and VLP curves and nodal analysis to diagnose and optimize wells."}},{name:{vi:"Khai thác cơ học",en:"Artificial lift"},desc:{vi:"Vận hành và tối ưu gaslift, bơm điện chìm và xử lý mất ổn định dòng chảy.",en:"Operate and optimize gas lift and ESPs and handle flow instability."}},{name:{vi:"Số liệu sản lượng",en:"Production data"},desc:{vi:"Kiểm soát phép thử, phân bổ sản lượng và phân loại hao hụt chính xác.",en:"Control well tests, allocation and accurate deferment classification."}},{name:{vi:"An toàn công nghệ",en:"Process safety"},desc:{vi:"Tôn trọng liên động, chỉ bypass theo phiếu phê duyệt và đánh giá rủi ro.",en:"Respect trips and only bypass with an approved permit and risk assessment."}},{name:{vi:"Phối hợp đa ngành",en:"Cross-discipline coordination"},desc:{vi:"Làm việc với bảo dưỡng, vỉa, khoan và bờ để ra quyết định nhanh và an toàn.",en:"Work with maintenance, reservoir, drilling and onshore teams for fast and safe decisions."}}],knowledge:{vi:["Luật Dầu khí số 12/2022/QH15 và yêu cầu về báo cáo khai thác, an toàn dầu khí.","API RP 14C về phân tích, thiết kế, lắp đặt và thử nghiệm hệ thống an toàn cho thiết bị khai thác ngoài khơi.","IEC 61511 về hệ thống an toàn công nghệ và quản lý bypass, override.","Phân tích giếng: chỉ số năng suất (PI), đường IPR và VLP, gaslift, độ ngậm nước, GOR.","API MPMS về đo lường dầu khí và nguyên tắc phân bổ sản lượng từ đồng hồ thương mại về giếng."],en:["Petroleum Law No. 12/2022/QH15 and requirements on production reporting and petroleum safety.","API RP 14C on analysis, design, installation and testing of offshore production safety systems.","IEC 61511 on safety instrumented systems and bypass and override management.","Well analysis: productivity index (PI), IPR and VLP curves, gas lift, water cut and GOR.","API MPMS on petroleum measurement and allocation principles from fiscal meters to wells."]},tools:["Hệ thống điều khiển phân tán (DCS)","Phần mềm phân tích nút giếng","Hệ thống báo cáo sản lượng ngày","Bình tách thử giếng","Hệ thống giám sát rung","Hệ thống PTW và MOC điện tử"],kpis:{vi:["Hiệu suất khai thác: sản lượng thực trên tiềm năng giếng.","Tỷ lệ hao hụt ngoài kế hoạch trên tổng tiềm năng.","Tỷ lệ giếng có phép thử hợp lệ đúng chu kỳ.","Số bypass hệ thống an toàn quá hạn (mục tiêu bằng 0)."],en:["Production efficiency: actual output over well potential.","Unplanned deferment as a share of total potential.","Share of wells with a valid test within the required cycle.","Overdue safety system bypasses (target zero)."]},day:[{time:"06:00",vi:"Giao ca, đọc nhật ký cảnh báo đêm và trạng thái từng giếng.",en:"Shift handover, read the overnight alarm log and each well's status."},{time:"08:00",vi:"Họp sản xuất với bảo dưỡng và bờ, thống nhất ưu tiên trong ngày.",en:"Production meeting with maintenance and onshore to agree daily priorities."},{time:"10:00",vi:"Thử giếng qua bình tách thử, kiểm tra chất lượng số liệu.",en:"Test a well through the test separator and check data quality."},{time:"14:00",vi:"Tối ưu phân phối khí gaslift giữa các giếng theo đường cong đáp ứng.",en:"Optimize lift gas distribution across wells using response curves."},{time:"17:00",vi:"Lập báo cáo sản lượng ngày, phân loại hao hụt và gửi về bờ.",en:"Prepare the daily production report, classify deferment and send it onshore."}],mistakes:{vi:["Tính hao hụt trên lưu lượng chất lỏng tổng thay vì dầu thực đã trừ nước.","Dùng phép thử giếng cũ đã bị thay thế để ước tính tiềm năng.","Bypass liên động an toàn bằng miệng để chạy lại nhanh, không có phiếu và đánh giá rủi ro."],en:["Calculating deferment on gross liquid instead of net oil after water.","Using an old, superseded well test to estimate potential.","Bypassing a safety trip verbally to restart quickly, without a permit or risk assessment."]},career:[{vi:"Kỹ sư vận hành khai thác tập sự",en:"Graduate production engineer"},{vi:"Kỹ sư vận hành khai thác",en:"Production operations engineer"},{vi:"Kỹ sư khai thác chính / giám sát vận hành",en:"Senior production engineer / superintendent"},{vi:"Quản lý vận hành mỏ / Tổng chỉ huy giàn",en:"Field operations manager / OIM"}],glossary:[{term:"Water cut",vi:"Độ ngậm nước: tỷ lệ nước trong tổng lưu lượng chất lỏng khai thác.",en:"The fraction of water in the total produced liquid."},{term:"GOR",vi:"Tỷ số khí dầu: thể tích khí khai thác trên mỗi thùng dầu ở điều kiện chuẩn.",en:"Gas-oil ratio: produced gas volume per barrel of oil at standard conditions."},{term:"Gas lift",vi:"Khai thác bằng khí nâng: bơm khí vào cần khai thác để giảm tỷ trọng cột chất lỏng.",en:"Injecting gas into the tubing to lighten the fluid column and lift production."},{term:"Deferment",vi:"Hao hụt sản lượng: phần sản lượng tiềm năng không khai thác được do dừng hoặc hạn chế.",en:"Production potential not delivered because of outages or constraints."},{term:"Override",vi:"Vô hiệu hóa tạm thời một chức năng an toàn, chỉ được phép theo quy trình phê duyệt.",en:"Temporarily disabling a safety function, allowed only through an approval process."}],quiz:[{q:{vi:"Giếng có chất lỏng 1500 bbl/ngày, ngậm nước 40%, dừng 12 giờ. Dầu hao hụt là bao nhiêu?",en:"A well makes 1500 bbl/d liquid at 40% water cut and is down 12 hours. What is the deferred oil?"},options:{vi:["750 bbl","300 bbl","900 bbl","450 bbl"],en:["750 bbl","300 bbl","900 bbl","450 bbl"]},answer:3,explain:{vi:"1500 x (1 - 0.4) x 12 / 24 = 450 bbl dầu thực.",en:"1500 x (1 - 0.4) x 12 / 24 = 450 bbl of net oil."}},{q:{vi:"Máy nén trip bất ngờ, không có trong kế hoạch bảo dưỡng. Hao hụt được xếp loại nào?",en:"A compressor trips unexpectedly and is not in the maintenance plan. How is the deferment classed?"},options:{vi:["Theo kế hoạch","Ngoài kế hoạch","Do bên ngoài","Không tính hao hụt"],en:["Planned","Unplanned","External","Not counted"]},answer:1,explain:{vi:"Sự cố thiết bị không có trong kế hoạch bảo dưỡng được duyệt là hao hụt ngoài kế hoạch.",en:"Equipment failure outside the approved maintenance plan is unplanned deferment."}},{q:{vi:"Trưởng ca yêu cầu bypass liên động rung cao để chạy lại ngay. Phản ứng đúng là gì?",en:"The shift supervisor wants to bypass a high vibration trip to restart now. What is the right response?"},options:{vi:["Bypass vì đã có người canh","Bypass trong 2 giờ rồi bật lại","Chỉ bypass theo phiếu phê duyệt, đánh giá rủi ro và người có thẩm quyền","Tắt cả hệ thống cảnh báo"],en:["Bypass since someone is watching","Bypass for 2 hours then restore","Bypass only with an approved permit, risk assessment and the authority","Disable the whole alarm system"]},answer:2,explain:{vi:"Rung cao có thể dẫn tới hỏng hóc nghiêm trọng; bypass chỉ hợp lệ khi qua quy trình phê duyệt chính thức.",en:"High vibration can lead to severe failure; a bypass is valid only through the formal approval process."}},{q:{vi:"Khi tính tiềm năng giếng, nên dùng phép thử nào?",en:"Which well test should be used to estimate well potential?"},options:{vi:["Phép thử hợp lệ gần nhất","Phép thử có lưu lượng cao nhất","Phép thử đầu tiên của giếng","Bình quân mọi phép thử"],en:["The latest valid test","The test with the highest rate","The well's first test","The average of all tests"]},answer:0,explain:{vi:"Phép thử hợp lệ gần nhất phản ánh đúng trạng thái giếng; phép thử cũ đã bị thay thế không được dùng.",en:"The latest valid test reflects the current well state; superseded tests must not be used."}}],tools_en:["Distributed control system (DCS)","Well nodal analysis software","Daily production reporting system","Well test separator","Vibration monitoring system","Electronic PTW and MOC system"]}}})})(window.KKR);
